w: [3]i32
for wi in 0..<3 {
	wv, okv := strconv.parse_int(fields[4+wi], 10)
	if !okv {
		return {}, fmt.tprintf("bad weights value %q (want integers): %s", fields[4+wi], line)
	}
	// range-check before the narrowing cast — a value beyond i32 that
	// wraps into the weight domain would silently mean a DIFFERENT
	// weight than the demo author wrote and get blessed into the
	// goldens (review finding). Fail loud at parse instead.
	if wv < int(min(i32)) || wv > int(max(i32)) {
		return {}, fmt.tprintf("weights value %q out of i32 range: %s", fields[4+wi], line)
	}
	w[wi] = i32(wv)
}
